// src/AppRouter.js
import { BrowserRouter, Routes, Route } from "react-router-dom";

// 🌐 PÚBLICAS
import HomePage from "./HomePage";
import LoginPage from "./LoginPage";
import RegisterPage from "./RegisterPage";
import SelectorTipoUsuarioPage from "./SelectorTipoUsuarioPage"; // ✅ NUEVA

// 👤 DEPORTISTA
import BuscarClubesPage from "./BuscarClubesPage";
import CanchasPage from "./CanchasPage";                 // ✅ aquí va /deportista/club/:clubId
import MisReservasPage from "./MisReservasPage";
import NotificacionesPage from "./NotificacionesPage";
import PerfilPage from "./PerfilPage";

// Flujo de reserva / pago (ya los tenías)
import Reservas from "./components/navigation/Reservas"; // la dejo tal cual
import ConfirmarReservaPage from "./containers/pages/ConfirmarReservaPage";
import ProcesarPagoPage from "./containers/pages/ProcesarPagoPage";
import ReservaExitosaPage from "./containers/pages/ReservaExitosaPage";

// 🏢 ADMIN (stub, para cuando hagas el dashboard)
import AdminDashboardPage from "./AdminDashboardPage";     // ✅ NUEVOS
import AdminCanchasPage from "./AdminCanchasPage";
import AdminReservasPage from "./AdminReservasPage";
import AdminPerfilPage from "./AdminPerfilPage";

export default function AppRouter() {
  return (
    <BrowserRouter>
      <Routes>
        {/* 🌐 PÚBLICAS */}
        <Route path="/" element={<HomePage />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/registrarse" element={<RegisterPage />} />

        {/* 👤 DEPORTISTA */}
        {/* Búsqueda de clubes */}
        <Route path="/deportista/buscar" element={<BuscarClubesPage />} />

        {/* Vista del club + selección de cancha
            Ejemplo: /deportista/club/2  */}
        <Route path="/deportista/club/:clubId" element={<CanchasPage />} />

        {/* Historial de reservas */}
        <Route path="/deportista/reservas" element={<MisReservasPage />} />

        {/* Notificaciones */}
        <Route
          path="/deportista/notificaciones"
          element={<NotificacionesPage />}
        />

        {/* Perfil deportista */}
        <Route path="/deportista/perfil" element={<PerfilPage />} />

        {/* Flujo de reserva y pago (tú ya tienes estas pantallas) */}
        <Route
          path="/deportista/confirmar-reserva"
          element={<ConfirmarReservaPage />}
        />
        <Route
          path="/deportista/procesar-pago"
          element={<ProcesarPagoPage />}
        />
        <Route
          path="/deportista/reserva-exitosa"
          element={<ReservaExitosaPage />}
        />

        {/* Ruta antigua que ya tenías, la dejo viva */}
        <Route path="/Reservas" element={<Reservas />} />

        {/* 🏢 ADMINISTRADOR */}
        <Route path="/admin/dashboard" element={<AdminDashboardPage />} />
        <Route path="/admin/canchas" element={<AdminCanchasPage />} />
        <Route path="/admin/reservas" element={<AdminReservasPage />} />
        <Route path="/admin/perfil" element={<AdminPerfilPage />} />
      </Routes>
    </BrowserRouter>
  );
}
